class Solution {ArrayList<ArrayList<int[]>> a;int[] time,low;int clock;ArrayList<Integer>out;void dfs(int u,int parent){time[u]=low[u]=clock++;for(int[] e:a.get(u))if(e[1]!=parent){int v=e[0];if(time[v]<0){dfs(v,e[1]);low[u]=Math.min(low[u],low[v]);if(low[v]>time[u])out.add(e[1]);}else low[u]=Math.min(low[u],time[v]);}}public int[] solve(int n,int[][] edges){a=new ArrayList<>();for(int i=0;i<n;i++)a.add(new ArrayList<>());for(int id=0;id<edges.length;id++){a.get(edges[id][0]).add(new int[]{edges[id][1],id});a.get(edges[id][1]).add(new int[]{edges[id][0],id});}time=new int[n];low=new int[n];Arrays.fill(time,-1);clock=0;out=new ArrayList<>();for(int u=0;u<n;u++)if(time[u]<0)dfs(u,-1);Collections.sort(out);return out.stream().mapToInt(Integer::intValue).toArray();}}